-- =============================================================================
-- Shared migration 005 — refresh_cadence.
--
-- GENERATED by scripts/gen_registry_seed.py from registry/document_types.csv.
--
-- Doc 4 Section 2: "In Operational Mode, Mandatory documents are ingested at
-- onboarding and refreshed at configured intervals." This is the column that
-- drives that. Read from the PLATFORM's refresh perspective, not the
-- document's own periodicity:
--
--   ONE_TIME    requested at onboarding; re-requested only on change or expiry
--   PERIODIC    re-fetched or re-requested on a schedule
--   CONTINUOUS  delta-loaded as transactions occur
--
-- NULL where in_scope is false: cadence is meaningless for a document this
-- repo does not ingest.
-- =============================================================================

ALTER TABLE platform_ref.document_type
    ADD COLUMN IF NOT EXISTS refresh_cadence text;

UPDATE platform_ref.document_type d
   SET refresh_cadence = v.cadence
  FROM (VALUES
    ('SALES_REGISTER', 'CONTINUOUS'),
