ALTER TABLE platform_ref.document_type
    ADD CONSTRAINT document_type_cadence_values_ck
    CHECK (refresh_cadence IN ('ONE_TIME', 'PERIODIC', 'CONTINUOUS'));

-- Mirrors document_type_scope_ck: everything we ingest is fully specified,
-- everything we do not is uniformly empty rather than defaulted.
ALTER TABLE platform_ref.document_type
    ADD CONSTRAINT document_type_cadence_scope_ck
    CHECK ((in_scope AND refresh_cadence IS NOT NULL)
        OR (NOT in_scope AND refresh_cadence IS NULL));
